async function api(path,options={}){
 const epoch=sessionEpoch,controller=new AbortController();controllers.add(controller)
 try{
  const headers={'Content-Type':'application/json','Accept-Language':locale.value,...(options.method&&options.method!=='GET'?{'X-CSRF-Token':csrf.value}:{})}
  const response=await fetch('/api'+path,{credentials:'same-origin',...options,signal:controller.signal,headers:{...headers,...options.headers},body:options.body===undefined?undefined:JSON.stringify(options.body)})
  const result=await response.json().catch(()=>({error:t('服务器返回了无效响应')}))
  if(epoch!==sessionEpoch)throw new DOMException(t('会话已更改'),'AbortError')
  if(!response.ok){if(response.status===401&&user.value)resetSession();throw new Error(result.error||t('请求失败'))}
  return result
 }finally{controllers.delete(controller)}
}
