 try{
  if(page.value==='overview'){dashboard.value=await api(`/dashboard?hours=${hours.value}&granularity=${granularity.value}&tz_offset=${-new Date().getTimezoneOffset()}`);[models.value,logs.value]=await Promise.all([api('/models'),api('/logs')]);if(admin.value)accounts.value=await api('/admin/accounts')}
  if(page.value==='keys')keys.value=await api('/keys')
  if(page.value==='logs')await loadLogs()
  if(page.value==='accounts'){accounts.value=await api('/admin/accounts');void refreshAccountQuotas()}
  if(page.value==='users'){[users.value,mailConfigured.value]=await Promise.all([api('/admin/users'),api('/admin/invitations/config').then(c=>c.configured)])}
  if(page.value==='models'){await loadModels();if(admin.value)accounts.value=await api('/admin/accounts')}
  if(page.value==='runtime')await runtimeLogs.value?.reload()
  if(page.value==='audit')await loadAudit()
  if(page.value==='settings'){days.value=(await api('/admin/settings')).log_retention_days;if(reloadEmail===true){await emailSettingsForm.value?.reload();await backupSettingsForm.value?.reload()}}
 }catch(e){if(e.name!=='AbortError')error.value=e.message}finally{await balance}
}
async function loadModels(){
 const request=++modelRequest;modelLoading.value=true
 try{
  const q=new URLSearchParams({page:String(modelPage.value),page_size:String(modelPageSize.value),q:modelSearch.value.trim()})
  if(admin.value&&modelAccount.value)q.set('account_id',modelAccount.value)
  if(modelProtocol.value)q.set('protocol',modelProtocol.value)
  if(modelStatus.value)q.set('status',modelStatus.value)
  const result=await api((admin.value?'/admin/models':'/models')+'?'+q)
  if(request!==modelRequest||page.value!=='models')return
  models.value=result.items;modelTotal.value=result.total
  if(modelPage.value>modelPages.value){modelPage.value=modelPages.value;await loadModels()}
 }finally{if(request===modelRequest)modelLoading.value=false}
}
