async function submitAuth(event){
 const submitted=new FormData(event.currentTarget)
 // Read the form at submission time: password managers may update input.value
 // without dispatching the input events used by Vue's v-model.
 if(initialized.value&&registering.value){registration.value={email:String(submitted.get('email')||''),real_name:String(submitted.get('real_name')||''),password:String(submitted.get('password')||'')}}
 else{auth.value.username=String(submitted.get('username')||'');auth.value.password=String(submitted.get('password')||'');if(!initialized.value)auth.value.setup_token=String(submitted.get('setup_token')||'')}
 await action(async()=>{if(initialized.value&&registering.value){const result=await api('/auth/register',{method:'POST',body:registration.value});auth.value.username=result.email;auth.value.password='';registration.value={email:'',real_name:'',password:''};registering.value=false;notify(t('注册成功，请使用邮箱登录；初始额度为 0，请联系管理员分配'));return}if(!initialized.value){await api('/setup',{method:'POST',body:{...auth.value,migration:setupMode.value==='migration'}});initialized.value=true;auth.value.setup_token='';if(setupMode.value!=='migration'){notify(t('管理员已创建，请登录'));return}}const me=await api('/auth/login',{method:'POST',body:{username:auth.value.username,password:auth.value.password}});resetSession();user.value=me.user;csrf.value=me.csrf_token;auth.value.password='';toast.value='';clearTimeout(toastTimer);if(admin.value)setupMigration.value=!!(await api('/admin/migrations/sub2api/onboarding')).pending;if(!setupMigration.value)await refresh()})}
