const money=n=>Math.round(Number(n)*1e6)
async function save(){await action(async()=>{
 const f=form.value
 let savedMessage=t('已保存')
 if(modal.value==='key'){const result=await api('/keys',{method:'POST',body:{name:f.name}});secret.value=result.token;await refresh();return}
 if(modal.value==='gateway'){const r=await api('/admin/gateway-accounts',{method:'POST',body:{name:f.name,...fromConfigForm(f.config)}});savedMessage=r.warning||t('网关已保存，已同步 {0} 个模型；请确认价格',[r.models?.length||0])}
 if(modal.value==='user'){const result=await api('/admin/invitations',{method:'POST',body:{email:f.email,display_name:f.display_name,limit_5h_microusd:money(f.limit5),limit_7d_microusd:money(f.limit7)}});savedMessage=result.warning||t('邀请邮件已提交发送')}
 if(modal.value==='quota')await api(`/admin/users/${f.id}/quota`,{method:'PUT',body:{limit_5h_microusd:money(f.limit5),limit_7d_microusd:money(f.limit7)}})
 if(modal.value==='import'){const result=await accountImportForm.value.submit();await refresh();notify(t('已导入 {0} / {1} 个账号',[result.imported,result.total]));return}
 if(modal.value==='routing')await accountRoutingForm.value.save()
 if(modal.value==='rename-account')await api(`/admin/accounts/${f.id}/name`,{method:'PUT',body:{name:f.name}})
 if(modal.value==='price')await api('/admin/models',{method:'PUT',body:{id:f.id,enabled:f.enabled,price:{input:money(f.input),output:money(f.output),cached:money(f.cached),cache_write:money(f.cache_write)}}})
 if(modal.value==='password'){await api('/me/password',{method:'PUT',body:{old_password:f.old_password,password:f.password}});resetSession()}
 if(modal.value==='reset-password')await api(`/admin/users/${f.id}/password`,{method:'PUT',body:{password:f.password}})
 if(modal.value==='settle')await api(`/admin/logs/${encodeURIComponent(f.id)}/settle`,{method:'POST',body:{amount:money(f.amount),reason:f.reason}})
 if(modal.value==='config'){await api(`/admin/accounts/${f.id}/config`,{method:'PUT',body:fromConfigForm(f.config)});savedMessage=t('配置已保存，请验证并同步')}
 if(modal.value==='oauth'){
  if(!oauth.value){oauth.value=await api(`/admin/oauth/${f.provider}/start`,{method:'POST',body:{name:f.name,account_id:f.account_id}});return}
  const result=await api(`/admin/oauth/${f.provider}/complete`,{method:'POST',body:{session_id:oauth.value.session_id,result:f.result,onboard:f.onboard}})
  if(result.warning)savedMessage=t('授权已保存，后续步骤需要检查：')+result.warning
 }
 modal.value=null;form.value={};await refresh();notify(savedMessage)
})}
async function resendInvitation(u){if(!confirm(t('重新向 {0} 发送设置密码链接？旧链接将失效，有效期为 24 小时。',[u.email])))return;await action(async()=>{const r=await api(`/admin/users/${u.id}/invitation`,{method:'POST',body:{}});await refresh();notify(r.warning||t('邀请邮件已提交发送'))})}
async function toggleUser(u){await action(async()=>{await api(`/admin/users/${u.id}/enabled`,{method:'PUT',body:{enabled:!u.enabled}});await refresh()})}
const quotaRefreshing=ref(false),quotaErrors=ref({})
let quotaTimer
async function refreshAccountQuotas(){
 if(quotaRefreshing.value||!admin.value||page.value!=='accounts')return
 const epoch=sessionEpoch
 quotaRefreshing.value=true
 try{
  for(const a of accounts.value.filter(a=>a.provider==='openai'&&a.enabled&&a.state!=='reauth_required')){
   if(epoch!==sessionEpoch||page.value!=='accounts')break
   try{await api(`/admin/accounts/${a.id}/quota/query`,{method:'POST',body:{}});delete quotaErrors.value[a.id]}
   catch(e){if(e.name==='AbortError')break;quotaErrors.value[a.id]=e.message}
  }
  if(epoch===sessionEpoch&&page.value==='accounts')accounts.value=await api('/admin/accounts')
 }catch(e){if(e.name!=='AbortError'&&epoch===sessionEpoch)error.value=e.message}
 finally{quotaRefreshing.value=false}
}
watch([page,admin],()=>{
 clearInterval(quotaTimer)
 if(page.value==='accounts'&&admin.value)quotaTimer=setInterval(refreshAccountQuotas,5*60*1000)
})
onBeforeUnmount(()=>clearInterval(quotaTimer))
async function queryQuota(a){await action(async()=>{await api(`/admin/accounts/${a.id}/quota/query`,{method:'POST',body:{}});delete quotaErrors.value[a.id];accounts.value=await api('/admin/accounts');await accountRoutingForm.value?.load();notify(t('上游额度快照已更新'))})}
async function resetRouting(a){if(!confirm(t('解除「{0}」的冷却并恢复调度？不会改变上游额度，下次请求可能再次被拒绝。',[a.name])))return;await action(async()=>{await api(`/admin/accounts/${a.id}/routing/reset`,{method:'POST',body:{}});await refresh();await accountRoutingForm.value?.load();notify(t('已恢复调度，等待实际请求验证'))})}
async function deleteAccount(a){if(!confirm(t('删除上游账号「{0}」？将擦除本地凭据并停止后续路由，历史日志及在途结算关联保留。此操作不可恢复。',[a.name])))return;await action(async()=>{await api(`/admin/accounts/${a.id}`,{method:'DELETE'});await refresh();notify(t('上游账号已删除'))})}
const cooling=a=>(a.health?.cooldowns||[]).some(c=>!c.scope&&c.until*1000>now.value)
async function toggleAccount(a){await action(async()=>{await api(`/admin/accounts/${a.id}/enabled`,{method:'PUT',body:{enabled:!a.enabled}});await refresh()})}
async function verify(a){await action(async()=>{const r=await api(`/admin/accounts/${a.id}/verify`,{method:'POST',body:{}});await refresh();accountModelsRevision.value++;open('account-models',accounts.value.find(item=>item.id===a.id)||a);notify(t('已同步 {0} 个模型',[r.models.length]))})}
async function revoke(k){if(!confirm(t('撤销密钥「{0}」？使用它的客户端将无法继续调用。',[k.name])))return;await action(async()=>{await api(`/keys/${k.id}/revoke`,{method:'POST',body:{}});await refresh()})}
async function deleteKey(k){if(!confirm(t('删除密钥「{0}」？此操作不可恢复，客户端将无法继续使用；历史日志与计费记录仍保留。',[k.name])))return;await action(async()=>{await api(`/keys/${k.id}`,{method:'DELETE'});await refresh();notify(t('密钥已删除'))})}
async function resetQuota(u){if(!confirm(t('重置 {0} 的两个额度窗口？已接收的请求仍结算到原窗口。',[u.username])))return;await action(async()=>{await api(`/admin/users/${u.id}/quota/reset`,{method:'POST',body:{kind:'both'}});await refresh();notify(t('额度窗口已重置'))})}
const copyingKey=ref(0)
async function copyKey(key){if(copyingKey.value)return;copyingKey.value=key.id;try{const result=await api(`/keys/${key.id}/reveal`,{method:'POST',body:{}});await copy(result.token)}catch(e){notify(e.message)}finally{copyingKey.value=0}}
async function useKey(key){if(key.enabled){await action(async()=>{const result=await api(`/keys/${key.id}/reveal`,{method:'POST',body:{}});open('key-usage',{...key,token:result.token})})}else open('key-usage',key)}
async function copy(value){try{await copyText(value);notify(t('已复制'))}catch{notify(t('请手动选择并复制内容'))}}
window.addEventListener('keydown',e=>{if(!modal.value)return;if(e.key==='Escape'){close();return}if(e.key==='Tab'){const items=[...document.querySelectorAll('.modal button:not(:disabled),.modal input:not(:disabled),.modal select:not(:disabled),.modal textarea:not(:disabled),.modal a[href]')];if(items.length){const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}})
async function editConfig(account){await action(async()=>{const cfg=await api(`/admin/accounts/${account.id}/config`);open('config',{...account,config:toConfigForm(cfg)})})}
window.addEventListener('hashchange',()=>{if(captureContribution()||captureInvitation())return;if(!user.value)return;const value=location.hash.slice(1);if(nav.value.some(n=>n.id===value)&&page.value!==value){page.value=value;refresh()}})

const compact=n=>new Intl.NumberFormat(locale.value,{notation:'compact',maximumFractionDigits:2}).format(Number(n)||0)
const statCards=computed(()=>{const d=dashboard.value;return [
 {label:t('API 密钥'),value:d.keys||0,note:t('{0} 启用',[d.enabled_keys||0]),icon:'key',color:'blue',accent:true},
 {label:admin.value?t('账号'):t('可用模型'),value:admin.value?(d.accounts||0):models.value.length,note:admin.value?t('{0} 启用',[d.enabled_accounts||0]):t('已启用且配置价格'),icon:'models',color:'purple',accent:true},
 {label:t('今日请求'),value:d.today_requests||0,note:t('总计: {0}',[d.total_requests||0]),icon:'chart',color:'green'},
 {label:admin.value?t('用户'):t('当前账号'),value:admin.value?(d.users||0):user.value?.username,note:admin.value?t('{0} 已启用',[d.enabled_users||0]):t('团队成员'),icon:'users',color:'teal',accent:true},
 {label:t('今日 Token'),value:compact(d.today_tokens),note:usd(d.today_amount),icon:'box',color:'amber',accent:true},
 {label:t('总 Token'),value:compact(d.total_tokens),note:usd(d.total_amount),icon:'models',color:'indigo',accent:true},
 {label:t('性能指标'),value:`${d.rpm||0} RPM`,note:`${compact(d.tpm)} TPM`,icon:'bolt',color:'purple'},
 {label:t('平均响应'),value:((d.average_ms||0)/1000).toFixed(2)+'s',note:t('{0} 活跃用户',[d.active_users||0]),icon:'clock',color:'rose'}]})
const palette=['#3b82f6','#10b981','#8b5cf6','#06b6d4','#f59e0b','#f43f5e']
const distributionRequests=computed(()=>dashboard.value.distribution.reduce((n,m)=>n+m.requests,0))
const errorStats=computed(()=>dashboard.value.errors||[])
const errorTotal=computed(()=>errorStats.value.reduce((n,e)=>n+e.requests,0))
const errorRate=computed(()=>distributionRequests.value?(errorTotal.value/distributionRequests.value*100).toFixed(1):'0.0')
const errorMax=computed(()=>Math.max(1,...errorStats.value.map(e=>e.requests)))
const errorLabel=status=>({400:t('请求错误'),401:t('认证失败'),403:t('无权限'),404:t('未找到'),408:t('请求超时'),429:t('限流'),500:t('内部错误'),502:t('上游错误'),503:t('服务不可用'),504:t('网关超时')}[status]||t('请求失败'))
const donutGradient=computed(()=>{const total=distributionRequests.value;if(!total)return '#eef2f6';let position=0;return 'conic-gradient('+dashboard.value.distribution.map((m,i)=>{const start=position;position+=m.requests/total*100;return `${palette[i%palette.length]} ${start}% ${position}%`}).join(',')+')'})
const chartSeries=[{key:'input',label:'Input',color:'#3b82f6'},{key:'output',label:'Output',color:'#10b981'},{key:'cache_write',label:'Cache Creation',color:'#f59e0b'},{key:'cached',label:'Cache Read',color:'#06b6d4'}]
const chartPoints=computed(()=>{const step=granularity.value==='day'?86400:3600;const end=Math.floor(now.value/1000/step)*step;const start=Math.floor((now.value/1000-Number(hours.value)*3600)/step)*step;const existing=new Map(dashboard.value.trend.map(p=>[p.time,p]));const values=[];for(let time=start;time<=end;time+=step)values.push(existing.get(time)||{time,input:0,output:0,cached:0,cache_write:0});return values})
const chartMax=computed(()=>Math.max(1,...chartPoints.value.flatMap(p=>chartSeries.filter(s=>!hiddenSeries.value.includes(s.key)).map(s=>p[s.key]||0))))
const pointsFor=key=>chartPoints.value.map((p,i)=>`${50+i*710/Math.max(chartPoints.value.length-1,1)},${200-(p[key]||0)/chartMax.value*180}`).join(' ')
const areaFor=key=>'50,200 '+pointsFor(key)+' 760,200'
const chartTicks=computed(()=>{const points=chartPoints.value;return [...new Set([0,Math.floor((points.length-1)/2),points.length-1])].map(i=>({i,time:points[i]?.time}))})
const chartDate=n=>new Date(n*1000).toLocaleString(locale.value,{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})
function toggleSeries(key){hiddenSeries.value=hiddenSeries.value.includes(key)?hiddenSeries.value.filter(k=>k!==key):[...hiddenSeries.value,key]}

const modalTitle=computed(()=>({'key-usage':t('使用 API 密钥'),'contribution-links':t('贡献链接'),'import':t('导入上游账号'),'routing':t('账号调度与健康'),'attempts':t('请求路由详情'),'rename-account':t('修改账号名称'),'account-models':t('已同步模型'),gateway:t('接入 API Key 网关'),config:t('账号兼容与连接配置'),key:secret.value?t('保存你的密钥'):t('创建 API 密钥'),user:t('添加团队成员'),quota:t('分配额度'),price:t('模型折算价格'),oauth:form.value.account_id?t('重新授权账号'):t('添加上游账号'),password:t('修改我的密码'),'reset-password':t('重置成员密码'),settle:t('人工核算'),settlement:t('结算详情')}[modal.value]||''))
</script>

<template>
 <div v-if="!user||setupMigration||contributionToken||invitationToken" class="public-language"><LanguageSelect/></div>
 <ContributionPage v-if="contributionToken" :key="contributionToken" :token="contributionToken"/>
 <InvitationPage v-else-if="invitationToken" :key="invitationToken" :token="invitationToken" @done="invitationDone" @cancel="invitationToken=''"/>
 <div v-else-if="loading" class="loading-screen"><span class="brand-mark">F</span><p>{{ t('正在连接你的工作空间…') }}</p></div>
 <div v-else-if="!user" class="auth-layout">
  <div class="auth-story"><a class="brand"><span class="brand-mark">F</span><span class="brand-name">FiftyAPI<small>v{{ version }}</small></span></a><div class="story-copy"><span class="eyebrow">A SMALLER GATEWAY.</span><h1>{{ t('模型连接，') }}<br>{{ t('简单一点。') }}</h1><p>{{ t('把账号、额度和调用记录放在一起。') }}<br>{{ t('为小团队保留刚刚好的管理能力。') }}</p><div class="story-line"></div><span class="story-note">Claude · OpenAI · Antigravity</span></div><span class="story-footer">YOUR MODELS. YOUR WORKSPACE.</span></div>
  <main class="auth-main"><form class="auth-card" @submit.prevent="submitAuth">
   <span class="eyebrow">{{ initialized?(registering?'CREATE YOUR ACCOUNT':'WELCOME BACK'):'LET’S GET STARTED' }}</span>
   <h2>{{ initialized?(registering?t('注册账号'):t('登录工作空间')):t('创建管理员账号') }}</h2>
   <p class="subtle">{{ initialized?(registering?t('填写邮箱、真实姓名和密码，创建你的账号。'):t('使用邮箱或原有用户名登录。')):t('首次设置完成后，公开初始化入口将关闭。') }}</p>
   <fieldset v-if="!initialized" class="setup-mode"><legend>{{ t('你准备如何开始？') }}</legend><label :class="{selected:setupMode==='new'}"><input type="radio" v-model="setupMode" value="new"> <span><strong>{{ t('全新使用 FiftyAPI') }}</strong><small>{{ t('创建管理员，稍后添加账号和成员。') }}</small></span></label><label :class="{selected:setupMode==='migration'}"><input type="radio" v-model="setupMode" value="migration"> <span><strong>{{ t('从 sub2api Docker 迁移') }}</strong><small>{{ t('创建管理员后，按网页引导迁入用户、原 Key 和账号。') }}</small></span></label></fieldset>
   <template v-if="initialized&&registering">
    <label>{{ t('邮箱') }}<input v-model="registration.email" name="email" type="email" autocomplete="email" required maxlength="254" :placeholder="t('你的邮箱地址')"></label>
    <label>{{ t('真实姓名') }}<input v-model="registration.real_name" name="real_name" autocomplete="name" required maxlength="80" :placeholder="t('请填写真实姓名')"></label>
    <label>{{ t('密码') }}<input v-model="registration.password" name="password" type="password" autocomplete="new-password" required minlength="8" maxlength="72" :placeholder="t('8–72 字节')"></label>
    <p class="notice">{{ t('注册后初始额度为 0，请联系管理员分配使用额度。') }}</p>
   </template>
   <template v-else>
    <label>{{ t('用户名') }}<input v-model="auth.username" name="username" autocomplete="username" required :minlength="initialized?1:3" :maxlength="initialized?254:64" :placeholder="initialized?t('邮箱或原有用户名'):t('管理员用户名')"></label>
    <label>{{ t('密码') }}<input v-model="auth.password" name="password" type="password" :autocomplete="initialized?'current-password':'new-password'" required :minlength="initialized?1:8" maxlength="72" :placeholder="initialized?t('输入密码'):t('至少 8 个字符')"></label>
    <label v-if="!initialized">{{ t('初始化口令（Setup token）') }}<input v-model="auth.setup_token" name="setup_token" type="password" required autocomplete="off" aria-describedby="setup-token-help" :placeholder="t('粘贴从服务器获取的初始化口令')"></label>
    <div v-if="!initialized" id="setup-token-help" class="setup-token-help">
     <p>{{ t('初始化口令用于确认你有服务器访问权限，仅首次创建管理员时使用，不是登录密码或主密钥。') }}</p>
     <p>{{ t('Docker 部署：在服务器终端执行以下命令，将输出的口令填入上方。容器名称不同时请替换 fiftyapi。') }}</p>
     <pre><code>docker exec fiftyapi cat /data/setup-token</code></pre>
     <p>{{ t('按快速开始部署时，也可读取宿主机 ./data/setup-token。直接运行程序时，读取数据库同目录的 setup-token；使用本地启动脚本时为 .local/setup-token。若设置了 FIFTYAPI_SETUP_TOKEN，则使用该环境变量的值。') }}</p>
    </div>
   </template>
   <div v-if="error" class="alert error" role="alert">{{ t(error) }}</div>
   <button class="primary wide" :disabled="busy">{{ busy?t('正在处理…'):initialized?(registering?t('注册'):t('登录')):(setupMode==='migration'?t('创建管理员并开始迁移'):t('创建管理员')) }} <span>→</span></button>
   <p v-if="initialized" class="auth-foot">{{ registering?t('已有账号？'):t('还没有账号？') }} <button class="text-button" type="button" :disabled="busy" @click="toggleRegistration">{{ registering?t('返回登录'):t('注册账号') }}</button></p>
   <p v-else class="auth-foot">{{ t('此账号用于管理上游连接与团队成员。') }}</p>
  </form></main>
 </div>
 <main v-else-if="setupMigration&&admin" class="migration-onboarding"><header><a class="brand"><span class="brand-mark">F</span><span class="brand-name">FiftyAPI</span></a><button type="button" class="text-button" :disabled="busy||setupMigrationForm?.busy" @click="finishMigration('overview')">{{ t('暂不迁移，进入控制台') }}</button></header><section class="migration-onboarding-card"><p class="eyebrow">{{ t('管理员已就绪 · Docker 迁移向导') }}</p><h1>{{ t('迁移你的 sub2api 工作空间') }}</h1><p class="subtle">{{ t('按下面四步完成，无需阅读额外文档。中途刷新或重新登录后可继续引导；上传文件需要重新选择。') }}</p><Sub2APIMigration ref="setupMigrationForm" :api="api" :busy="busy" onboarding @finish="finishMigration"/><p v-if="error" class="alert error" role="alert">{{ t(error) }}</p></section></main>
 <div v-else class="workspace">
  <aside :class="['sidebar',{shown:mobileNav}]"><a class="brand" href="#overview" @click.prevent="go('overview')"><span class="brand-mark">F</span><span class="brand-name">FiftyAPI<small>v{{ version }}</small></span></a><div class="workspace-tag"><span class="green-dot"></span> {{ t('团队工作空间') }} <span class="tag">{{ admin?t('管理员'):t('成员') }}</span></div><div class="nav-label">{{ t('工作台') }}</div><nav :aria-label="t('主导航')"><button v-for="n in nav" :key="n.id" :class="['nav-item',{active:page===n.id}]" @click="go(n.id)"><span class="nav-icon"><Icon :name="n.icon"/></span>{{ n.name }}</button></nav><div class="sidebar-bottom"><button class="profile" @click="open('password')"><span class="avatar">{{ user.username.slice(0,1).toUpperCase() }}</span><span><b>{{ user.username }}</b><small>{{ admin?t('工作空间管理员'):t('团队成员') }}</small></span><span class="profile-dots">⌄</span></button><button class="logout" @click="logout" :disabled="busy">{{ t('退出登录 ↗') }}</button></div></aside>
  <div v-if="mobileNav" class="nav-scrim" @click="mobileNav=false"></div>
  <main class="main-content"><header class="topbar"><button class="mobile-menu icon-button" :aria-label="t('打开菜单')" @click="mobileNav=!mobileNav"><Icon name="menu"/></button><div><div class="header-page"><h1>{{ title }}</h1><small>{{ page==='overview'?t('系统概览与统计数据'):description }}</small></div></div><div class="header-controls"><LanguageSelect/><button class="secondary refresh-button" :disabled="busy||headerRefreshing" @click="refreshCurrentPage" :aria-label="t('刷新当前页面')">↻ <span>{{ headerRefreshing?t('刷新中…'):t('刷新') }}</span></button><span class="header-balance" :title="balanceError?t('余额更新失败：')+balanceError+t('；点击刷新重试'):t('5 小时剩余额度')"><Icon name="box"/> {{ headerQuota?usd(Math.max(0,headerQuota.limit-headerQuota.used-headerQuota.reserved)):(balanceError?t('余额加载失败'):t('余额加载中…')) }}<small v-if="balanceError&&headerQuota">{{ t('更新失败') }}</small></span><button class="header-user" @click="open('password')"><span class="avatar">{{ user.username.slice(0,2).toUpperCase() }}</span><span><strong>{{ user.username }}</strong><small>{{ admin?t('管理员'):t('成员') }}</small></span><span class="user-chevron">⌄</span></button></div></header>
   <div class="page-content"><div class="page-heading" :class="{'page-toolbar':page!=='overview'}" v-if="['overview','keys','accounts','users'].includes(page)"><div v-if="page==='overview'"><span class="eyebrow">{{ page==='overview'?'WORKSPACE OVERVIEW':page.toUpperCase() }}</span><h1>{{ title }}</h1><p>{{ description }}</p></div><div v-if="page==='keys'" class="notice toolbar-notice">{{ t('点击密钥旁的图标复制完整密钥。不同密钥共享你的 5 小时和每周额度。') }}</div><div v-if="page==='accounts'" class="notice toolbar-notice">{{ t('授权后会自动发现模型。目录就绪表示已取得模型列表，具体模型权限以实际调用为准。') }}</div><div class="heading-actions"><button v-if="page==='keys'" class="secondary" @click="open('key-usage')">{{ t('使用说明') }}</button><button v-if="page==='keys'" class="primary" @click="open('key')">{{ t('＋ 创建密钥') }}</button><button v-if="page==='accounts'" class="primary" @click="open('gateway')">{{ t('+接入上游API') }}</button><button v-if="page==='accounts'" class="primary" @click="open('oauth')">{{ t('＋ 添加账号') }}</button><button v-if="page==='accounts'" class="secondary" @click="open('import')">{{ t('导入账号') }}</button><button v-if="page==='accounts'" class="secondary" @click="open('contribution-links')">{{ t('贡献链接') }}</button><button v-if="page==='users'" class="primary" @click="open('user')">{{ t('＋ 添加成员') }}</button></div></div>
    <div v-if="error&&!modal" class="alert error" role="alert">{{ t(error) }}</div>
    <template v-if="page==='overview'">
     <div class="dashboard-stats"><article v-for="stat in statCards" :key="stat.label" class="dashboard-stat"><span :class="['stat-icon',stat.color]"><Icon :name="stat.icon"/></span><div><span class="stat-label">{{ stat.label }}</span><strong>{{ stat.value }}</strong><p :class="{'stat-note-accent':stat.accent}">{{ stat.note }}</p></div></article></div>
     <section class="panel quick-panel"><h2>{{ t('快捷操作') }}</h2><div class="quick-grid"><button v-for="quick in (admin?[{page:'users',icon:'users',label:t('分配用户额度'),note:t('管理成员与 5 小时 / 每周预算')},{page:'accounts',icon:'accounts',label:t('管理上游账号'),note:t('授权连接、模型同步与可用状态')}]:[{page:'keys',icon:'key',label:t('创建 API 密钥'),note:t('连接 Claude Code 与 Codex')},{page:'logs',icon:'logs',label:t('查看使用记录'),note:t('请求状态、Token 与额度消耗')}])" :key="quick.page" class="quick-action" @click="go(quick.page)"><span class="quick-icon"><Icon :name="quick.icon"/></span><span><strong>{{ quick.label }}</strong><small>{{ quick.note }}</small></span><Icon class="quick-chevron" name="chevron"/></button></div></section>
     <div class="quota-grid"><article class="quota-card" v-for="w in quota" :key="w.kind"><div class="card-kicker"><span>{{ w.kind==='5h'?t('5 小时额度'):t('每周额度') }}</span><span class="pill">{{ w.expires_at?t('使用中'):t('等待首次调用') }}</span></div><div class="quota-amount">{{ usd(Math.max(0,w.limit-w.used-w.reserved)) }}<span>{{ t('剩余 /') }} {{ usd(w.limit) }}</span></div><div class="meter"><span :style="{width:percent(w)+'%'}" :class="{warning:percent(w)>85}"></span></div><div class="quota-detail"><span>{{ t('已用') }} {{ usd(w.used) }}<template v-if="w.reserved"> {{ t('· 预占') }} {{ usd(w.reserved) }}</template></span><span :title="date(w.expires_at)">{{ w.expires_at?remaining(w.expires_at):t('首次正金额结算后开始计时') }}</span></div></article></div>
     <section class="panel dashboard-filter"><label>{{ t('时间范围：') }}<select v-model="hours" @change="refresh"><option value="24">{{ t('近 24 小时') }}</option><option value="168">{{ t('近 7 天') }}</option><option value="720">{{ t('近 30 天') }}</option></select></label><button class="secondary" @click="refresh"><Icon name="refresh"/> {{ t('刷新') }}</button><span class="filter-spacer"></span><label>{{ t('粒度：') }}<select v-model="granularity" @change="refresh"><option value="hour">{{ t('按小时') }}</option><option value="day">{{ t('按天') }}</option></select></label></section>
     <div class="analytics-grid"><section class="panel analytics-panel"><div class="panel-heading"><h2>{{ t('模型分布') }}</h2><span class="chart-caption">{{ t('所选时间内的请求') }}</span></div><div class="distribution-layout"><div class="donut" :style="{background:donutGradient}"><div><strong>{{ distributionRequests }}</strong><span>{{ t('请求总数') }}</span></div></div><div class="distribution-table"><table><thead><tr><th>{{ t('模型') }}</th><th>{{ t('请求') }}</th><th>Token</th><th>{{ t('消耗') }}</th></tr></thead><tbody><tr v-for="(m,i) in dashboard.distribution" :key="m.model"><td :title="m.model"><span class="model-color" :style="{background:palette[i%palette.length]}"></span>{{ m.model }}</td><td>{{ m.requests }}</td><td>{{ compact(m.tokens) }}</td><td class="cost-cell">{{ usd(m.amount) }}</td></tr><tr v-if="!dashboard.distribution.length"><td colspan="4" class="chart-table-empty">{{ t('尚无模型用量记录') }}</td></tr></tbody></table></div></div></section>
     <section class="panel analytics-panel"><div class="panel-heading"><h2>{{ t('Token 使用趋势') }}</h2><span class="chart-caption">{{ hours==='24'?t('近 24 小时'):hours==='168'?t('近 7 天'):t('近 30 天') }}</span></div><div class="chart-legend"><button v-for="series in chartSeries" :key="series.key" :class="{disabled:hiddenSeries.includes(series.key)}" @click="toggleSeries(series.key)" :aria-pressed="!hiddenSeries.includes(series.key)"><i :style="{borderColor:series.color,background:series.color+'18'}"></i>{{ series.label }}</button></div><div class="trend-chart"><svg viewBox="0 0 780 245" role="img" :aria-label="t('Token 使用趋势')"><defs><linearGradient v-for="series in chartSeries" :key="series.key" :id="'fill-'+series.key" x1="0" y1="0" x2="0" y2="1"><stop :stop-color="series.color" stop-opacity="0.15"/><stop offset="1" :stop-color="series.color" stop-opacity="0.02"/></linearGradient></defs><g v-for="i in [0,1,2,3,4]" :key="i"><line x1="50" x2="760" :y1="20+i*45" :y2="20+i*45" stroke="#e5e7eb" stroke-width="1"/><text x="40" :y="24+i*45" text-anchor="end" fill="#6b7280" font-size="11">{{ compact(chartMax*(4-i)/4) }}</text></g><template v-for="series in chartSeries" :key="series.key"><template v-if="!hiddenSeries.includes(series.key)&&dashboard.trend.length"><polygon :points="areaFor(series.key)" :fill="'url(#fill-'+series.key+')'"/><polyline :points="pointsFor(series.key)" fill="none" :stroke="series.color" stroke-width="2.5" stroke-linejoin="round"/><circle v-for="(p,i) in chartPoints" :key="i" :cx="50+i*710/Math.max(chartPoints.length-1,1)" :cy="200-(p[series.key]||0)/chartMax*180" r="2.7" :fill="series.color"><title>{{ date(p.time) }} · {{ series.label }} {{ p[series.key]||0 }}</title></circle></template></template><text v-for="tick in chartTicks" :key="tick.i" :x="50+tick.i*710/Math.max(chartPoints.length-1,1)" y="227" text-anchor="middle" fill="#6b7280" font-size="10">{{ chartDate(tick.time) }}</text></svg><span v-if="!dashboard.trend.length" class="chart-empty-label">{{ t('所选时间内暂无 Token 用量') }}</span></div></section><section class="panel analytics-panel error-panel"><div class="panel-heading"><h2>{{ t('错误统计') }}</h2><span class="chart-caption">{{ t('所选时间 · HTTP ≥ 400') }}</span></div><div class="error-summary"><div><strong>{{ errorTotal }}</strong><span>{{ t('失败请求') }}</span></div><div><strong>{{ errorRate }}%</strong><span>{{ t('错误率') }}</span></div></div><div v-if="errorStats.length" class="error-bars" role="img" :aria-label="t('按 HTTP 状态码统计的错误请求')"><div v-for="e in errorStats" :key="e.status" class="error-bar-row"><div><span>{{ e.status }} · {{ errorLabel(e.status) }}</span><strong>{{ e.requests }}</strong></div><div class="error-bar-track"><span :style="{width:e.requests/errorMax*100+'%'}"></span></div></div></div><div v-else class="error-empty">{{ distributionRequests?t('所选时间内无错误请求'):t('所选时间内暂无请求') }}</div></section></div>
     <section class="panel"><div class="panel-heading"><h2>{{ t('最近使用记录') }}</h2><button class="text-button" @click="go('logs')">{{ t('查看全部 →') }}</button></div><div v-if="!logs.length" class="empty"><Icon class="empty-svg" name="chart"/><h3>{{ t('暂无请求记录') }}</h3><p>{{ t('创建 API 密钥并接入开发工具后，用量与请求状态会显示在这里。') }}</p><button class="secondary" @click="go('keys')">{{ t('管理 API 密钥') }}</button></div><div v-else class="recent-list"><div v-for="l in logs.slice(0,8)" :key="l.id"><span :class="['status-dot',{bad:l.status>=400}]"></span><b>{{ l.model }}</b><span>{{ date(l.created_at) }}</span><strong>{{ l.amount===null?t('待核算'):usd(l.amount) }}</strong></div></div></section>
     <p class="dashboard-footnote">{{ t('统计基于当前保留的请求日志。金额为内部额度折算，不代表 OAuth 订阅的实际账单。') }}</p>
    </template>
    <template v-if="page==='keys'"><section class="panel"><form class="model-search key-search" @submit.prevent="searchKeys"><label>{{ t('名称') }}<input v-model="keyFilter.name" maxlength="80" :placeholder="t('密钥名称关键词')"></label><label>{{ t('密钥前缀') }}<input v-model="keyFilter.prefix" maxlength="100" :placeholder="t('前缀关键词')"></label><label>{{ t('状态') }}<select :aria-label="t('密钥状态')" v-model="keyFilter.status"><option value="">{{ t('全部状态') }}</option><option value="enabled">{{ t('使用中') }}</option><option value="revoked">{{ t('已撤销') }}</option></select></label><label>{{ t('创建开始时间') }}<input v-model="keyFilter.since" type="datetime-local"></label><label>{{ t('创建结束时间') }}<input v-model="keyFilter.until" type="datetime-local" :min="keyFilter.since||undefined"></label><button class="secondary">{{ t('筛选') }}</button><button type="button" class="secondary" @click="clearKeys">{{ t('清除') }}</button></form><div v-if="!keys.length" class="empty"><span class="empty-icon">⌘</span><h3>{{ t('你的第一把 API 密钥') }}</h3><p>{{ t('可以按工具或设备分别创建，方便独立撤销。') }}</p><button class="primary" @click="open('key')">{{ t('创建密钥') }}</button></div><div v-else-if="!filteredKeys.length" class="empty"><h3>{{ t('暂无符合条件的密钥') }}</h3><p>{{ t('请调整筛选条件。') }}</p></div><div v-else class="table-wrap"><table><thead><tr><th>{{ t('名称') }}</th><th>{{ t('API 密钥') }}</th><th>{{ t('状态') }}</th><th>{{ t('创建时间') }}</th><th></th></tr></thead><tbody><tr v-for="k in pagedKeys" :key="k.id"><td><b>{{ k.name }}</b></td><td><div class="key-token"><code>{{ k.prefix.slice(0,6) }}...{{ k.suffix }}</code><button type="button" class="key-copy" :aria-label="t('复制密钥')" :title="k.enabled?t('复制密钥'):t('已撤销')" :disabled="!k.enabled||Boolean(copyingKey)" @click="copyKey(k)"><Icon name="copy"/></button></div></td><td><span :class="['pill',{'muted-pill':!k.enabled}]">{{ k.enabled?t('使用中'):t('已撤销') }}</span></td><td>{{ date(k.created_at) }}</td><td><div class="key-actions"><button type="button" class="text-button" @click="useKey(k)" :disabled="busy">{{ t('使用密钥') }}</button><button v-if="k.enabled" class="danger-text" :disabled="busy" @click="revoke(k)">{{ t('撤销') }}</button><button class="danger-text" :disabled="busy" @click="deleteKey(k)">{{ t('删除') }}</button></div></td></tr></tbody></table></div><ListPagination v-model:page="keyPage" v-model:size="keyPageSize" :total="filteredKeys.length" :pages="keyPages" :label="t('API 密钥')"/></section></template>
    <template v-if="page==='logs'"><div class="filter-bar"><input v-model="filter.request_id" :placeholder="t('完整请求 ID')" :aria-label="t('按请求 ID 筛选')"><input v-model="filter.model" :placeholder="t('按模型 ID 筛选')" :aria-label="t('按模型筛选')"><select v-model="filter.status" :aria-label="t('按状态筛选')"><option value="">{{ t('所有状态') }}</option><option value="200">{{ t('成功 200') }}</option><option value="400">{{ t('请求错误 400') }}</option><option value="429">{{ t('限流 429') }}</option><option value="502">{{ t('上游错误 502') }}</option><option value="503">{{ t('服务不可用 503') }}</option></select><select v-model="filter.hours" :aria-label="t('按时间筛选')"><option value="24">{{ t('近 24 小时') }}</option><option value="168">{{ t('近 7 天') }}</option><option value="720">{{ t('近 30 天') }}</option><option value="0">{{ t('全部保留记录') }}</option><option value="custom">{{ t('自定义时间') }}</option></select><template v-if="filter.hours==='custom'"><label class="log-time-filter">{{ t('开始时间') }}<input v-model="filter.since" type="datetime-local"></label><label class="log-time-filter">{{ t('结束时间') }}<input v-model="filter.until" type="datetime-local" :min="filter.since||undefined"></label></template><select v-if="admin" v-model="filter.settlement" :aria-label="t('结算状态筛选')"><option value="">{{ t('全部结算状态') }}</option><option value="pending">{{ t('结算异常') }}</option><option value="settled">{{ t('已结算') }}</option><option value="inflight">{{ t('处理中') }}</option></select><button class="secondary" @click="searchLogs" :disabled="busy||logLoading">{{ t('筛选') }}</button></div><section class="panel"><div v-if="!logs.length" class="empty"><span class="empty-icon">≡</span><h3>{{ t('还没有符合条件的请求') }}</h3><p>{{ t('这里只记录调用信息，不保存提示词与完整回复。') }}</p></div><div v-else class="table-wrap"><table class="request-log-table"><thead><tr><th>{{ t('时间') }}</th><th>{{ t('请求 ID') }}</th><th>{{ t('模型') }}</th><th v-if="admin">{{ t('用户') }}</th><th>{{ t('状态') }}</th><th>{{ t('输入 / 输出') }}</th><th>{{ t('耗时') }}</th><th>{{ t('额度消耗') }}</th><th>{{ t('路由 / 结算') }}</th></tr></thead><tbody><tr v-for="l in logs" :key="l.id"><td>{{ date(l.created_at) }}</td><td><button class="text-button request-id" :title="l.id" @click="copy(l.id)">{{ l.id.slice(0,12) }} ⧉</button></td><td><b>{{ l.model }}</b><small v-if="l.error" class="cell-note error-text">{{ t(l.error) }}</small></td><td v-if="admin">#{{ l.user_id }}</td><td><span :class="['pill',{'bad-pill':l.status>=400,'muted-pill':!l.status}]">{{ l.status||t('未记录') }}</span></td><td>{{ l.input_tokens??'—' }} / {{ l.output_tokens??'—' }}</td><td>{{ l.duration_ms }} ms</td><td>{{ l.amount===null?(l.settlement_status==='pending'?t('结算异常'):t('处理中')):usd(l.amount) }}</td><td><div class="log-row-actions"><button class="text-button" :disabled="busy" @click="open('attempts',l)">{{ t('路由详情') }}</button><template v-if="admin&&l.settlement_status"><button class="text-button" :disabled="busy||logLoading" @click="viewSettlement(l)">{{ t('详情') }}</button><template v-if="l.settlement_status==='pending'"><button class="text-button" :disabled="busy||logLoading" @click="retrySettlement(l)">{{ t('重试结算') }}</button><button class="danger-text" :disabled="busy||logLoading" @click="open('settle',l)">{{ t('人工核算') }}</button></template></template></div></td></tr></tbody></table></div><div class="model-pagination"><span>{{ t('共 {0} 项 · 第 {1} / {2} 页',[logTotal,logPage,logPages]) }}</span><div class="actions"><label class="page-size">{{ t('每页') }}<select :aria-label="t('日志每页条数')" v-model.number="logPageSize" :disabled="busy||logLoading" @change="searchLogs"><option :value="10">10</option><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select></label><button class="secondary" :disabled="busy||logLoading||logPage<=1" @click="turnLogPage(-1)">{{ t('上一页') }}</button><button class="secondary" :disabled="busy||logLoading||logPage>=logPages" @click="turnLogPage(1)">{{ t('下一页') }}</button></div></div></section></template>
    <template v-if="page==='accounts'"><div v-if="!accounts.length" class="panel empty"><span class="empty-icon">▦</span><h3>{{ t('连接第一个上游账号') }}</h3><p>{{ t('支持 OAuth 账号和 Sub2Api、FiftyAPI、New API 网关。') }}</p><button class="primary" @click="open('oauth')">{{ t('添加账号') }}</button><button class="primary" style="margin-left:10px" @click="open('gateway')">{{ t('+接入上游API') }}</button></div><div v-else class="account-grid"><article class="panel account-card" v-for="a in accounts" :key="a.id"><div class="account-card-top"><span :class="['provider-icon',a.provider]">{{ accountLabel(a).slice(0,1) }}</span><div class="account-heading"><h2>{{ a.name }}</h2><p class="subtle">{{ accountLabel(a) }} · #{{ a.id }}</p></div><span :class="['pill',{'bad-pill':a.state==='error'||a.state==='reauth_required','muted-pill':!a.enabled}]">{{ !a.enabled?t('已停用'):cooling(a)?t('冷却中'):(a.health?.cooldowns||[]).some(c=>c.scope&&c.until*1000>now)?t('部分模型冷却'):stateLabel(a.state) }}</span></div><div class="account-content"><div class="account-info"><p v-if="a.contribution_link_id" class="subtle">{{ t('贡献链接 #') }}{{ a.contribution_link_id }} · {{ date(a.contributed_at) }}</p><p class="account-model-count">{{ t('已保存') }} {{ a.model_count||0 }} {{ t('个模型') }}<span v-if="a.models_synced_at"> · {{ date(a.models_synced_at) }}</span></p><div v-if="a.scheduling" class="account-routing-summary"><span>{{ t('进行中') }} {{ a.active||0 }} / {{ a.scheduling.concurrency }}</span><span>{{ t('等待') }} {{ a.waiting||0 }}</span><span>{{ t('优先级') }} {{ a.scheduling.priority }} {{ t('· 权重') }} {{ a.scheduling.weight }}</span></div><details class="account-details"><summary>{{ t('授权与健康详情') }}</summary><p v-if="a.health?.reason" class="subtle account-health-note">{{ a.health.reason }}</p><p v-if="a.credential_info?.email||a.credential_info?.plan" class="subtle account-health-note">{{ a.credential_info.email }} · {{ a.credential_info.plan||t('套餐未返回') }} <span v-if="a.credential_info.account_hint">({{ a.credential_info.account_hint }})</span></p><p v-if="a.credential_info?.token_expires_at" class="subtle account-health-note">{{ t('授权到期：') }}{{ date(a.credential_info.token_expires_at) }} · {{ a.credential_info.refresh_available?t('可自动刷新'):t('无刷新令牌') }}</p></details><p v-if="a.credential_error" class="account-error">{{ a.credential_error }}</p><p v-if="a.last_error" class="account-error">{{ t(a.last_error) }}</p></div><section class="account-quota" :aria-label="t('上游额度')"><div class="account-quota-heading"><strong>{{ t('上游额度') }}</strong><button v-if="a.provider==='openai'" class="text-button" :disabled="busy||quotaRefreshing||!a.enabled" @click="queryQuota(a)">{{ t('刷新额度') }}</button></div><div class="routing-quota-grid"><div v-for="(window,index) in [{used:a.health?.primary_used_percent,reset:a.health?.primary_reset_at},{used:a.health?.secondary_used_percent,reset:a.health?.secondary_reset_at}]" :key="index" class="routing-quota"><strong>{{ index===0?t('主窗口'):t('次窗口') }}</strong><p>{{ window.used==null?t('暂无额度数据'):t('剩余 {0}%',[Math.max(0,100-window.used).toFixed(1)]) }}</p><div class="meter" :class="{'quota-meter-empty':window.used==null}"><span v-if="window.used!=null" :style="{width:Math.min(100,Math.max(0,window.used))+'%'}" :class="{warning:window.used>=85}"></span></div><small class="subtle">{{ window.reset?t('重置：')+date(window.reset):t('重置时间未返回') }}</small></div></div><p v-if="quotaErrors[a.id]" class="account-error" role="status">{{ t('查询失败：') }}{{ quotaErrors[a.id] }}{{ t('；保留上次快照') }}</p><p class="subtle">{{ a.health?.quota_observed_at?t('更新于 ')+date(a.health.quota_observed_at):t('尚无额度快照') }} · {{ a.provider==='openai'?t('本页每 5 分钟自动查询'): t('额度随上游请求返回时更新') }}</p></section></div><div class="account-actions"><button class="text-button" :disabled="busy" @click="open('routing',a)">{{ t('调度与健康') }}</button><button class="text-button" :disabled="busy" @click="open('account-models',a)">{{ t('查看模型') }}</button><button class="secondary" :disabled="busy||!a.enabled" @click="verify(a)">{{ t('验证并同步') }}</button><button class="text-button" :disabled="busy" @click="editConfig(a)">{{ t('配置') }}</button><button v-if="a.provider!=='gateway'" class="text-button" :disabled="busy" @click="open('oauth',a)">{{ t('重新授权') }}</button><button class="text-button" :disabled="busy" @click="toggleAccount(a)">{{ a.enabled?t('停用'):t('启用') }}</button><button class="text-button" :disabled="busy" @click="open('rename-account',a)">{{ t('改名') }}</button><button class="danger-text" :disabled="busy" @click="deleteAccount(a)">{{ t('删除') }}</button></div></article></div></template>
    <template v-if="page==='users'"><section class="panel"><form class="model-search member-search" @submit.prevent="searchMembers"><label>{{ t('成员 ID') }}<input v-model="memberFilter.id" type="number" min="1" step="1" :placeholder="t('全部成员')"></label><label>{{ t('名称') }}<input v-model="memberFilter.name" maxlength="200" :placeholder="t('用户名或显示名称')"></label><label>{{ t('邮箱') }}<input v-model="memberFilter.email" maxlength="254" :placeholder="t('邮箱关键词')"></label><label>{{ t('角色') }}<select :aria-label="t('角色')" v-model="memberFilter.role"><option value="">{{ t('全部角色') }}</option><option value="admin">{{ t('管理员') }}</option><option value="user">{{ t('成员') }}</option></select></label><label>{{ t('状态') }}<select :aria-label="t('状态')" v-model="memberFilter.status"><option value="">{{ t('全部状态') }}</option><option value="enabled">{{ t('已启用') }}</option><option value="pending">{{ t('待设置密码') }}</option><option value="disabled">{{ t('已停用') }}</option></select></label><button class="secondary">{{ t('筛选') }}</button><button class="secondary" type="button" @click="clearMembers">{{ t('清除') }}</button></form><div v-if="!filteredMembers.length" class="empty"><h3>{{ t('暂无符合条件的成员') }}</h3><p>{{ t('请调整筛选条件。') }}</p></div><div v-else class="table-wrap"><table class="member-table"><thead><tr><th>{{ t('成员 ID') }}</th><th>{{ t('用户名') }}</th><th>{{ t('显示名称') }}</th><th>{{ t('邮箱') }}</th><th>{{ t('角色') }}</th><th>{{ t('状态') }}</th><th>{{ t('5 小时 / 每周额度') }}</th><th>{{ t('管理') }}</th></tr></thead><tbody><tr v-for="u in pagedMembers" :key="u.id"><td>#{{ u.id }}</td><td><b>{{ u.username }}</b></td><td>{{ u.display_name||'—' }}</td><td>{{ u.email||'—' }}</td><td>{{ u.role==='admin'?t('管理员'):t('成员') }}</td><td><span :class="['pill',{'muted-pill':!u.enabled}]">{{ !u.enabled?t('已停用'):!u.password_set?t('待设置密码'):t('已启用') }}</span><small v-if="u.email" class="cell-note">{{ u.invitation_state==='expired'?t('链接已过期'):u.invitation_state==='accepted'?t('已设置密码'):u.mail_state==='failed'?t('邮件发送失败'):u.mail_state==='sending'?t('邮件发送中'):u.mail_state==='sent'?t('邮件已提交发送'):'' }}</small><small v-if="u.mail_error" class="cell-note error-text">{{ u.mail_error }}</small></td><td>{{ usd(u.limit_5h_microusd) }} / {{ usd(u.limit_7d_microusd) }}</td><td><div class="table-actions"><button class="text-button" @click="open('quota',u)">{{ t('分配额度') }}</button><button class="text-button" @click="resetQuota(u)">{{ t('重置窗口') }}</button><template v-if="u.role!=='admin'"><button v-if="u.email" class="text-button" :disabled="busy||!u.enabled||!mailConfigured" @click="resendInvitation(u)">{{ t('重新发送邀请') }}</button><button v-else class="text-button" @click="open('reset-password',u)">{{ t('重置密码') }}</button><button class="danger-text" @click="toggleUser(u)">{{ u.enabled?t('停用'):t('启用') }}</button></template></div></td></tr></tbody></table></div><ListPagination v-model:page="memberPage" v-model:size="memberPageSize" :total="filteredMembers.length" :pages="memberPages" :label="t('团队成员')"/></section></template>
    <template v-if="page==='models'"><div class="notice">{{ t('协议由上游账号配置决定，不自动转换；同一模型可以支持多种协议。价格单位：USD / 百万 Token。用于内部额度折算，不代表 OAuth 订阅实际收费。缺少价格的模型不开放调用。') }}</div><section class="panel"><form class="model-search" @submit.prevent="searchModels"><label>{{ t('搜索模型') }}<input v-model="modelSearch" maxlength="200" :placeholder="t('模型 ID、上游模型或平台')"></label><label v-if="admin">{{ t('上游账号') }}<select :aria-label="t('筛选上游账号')" v-model="modelAccount" :disabled="busy||modelLoading" @change="searchModels"><option value="">{{ t('全部账号') }}</option><option v-for="a in accounts" :key="a.id" :value="String(a.id)">{{ a.name }} · {{ accountLabel(a) }} #{{ a.id }}</option></select></label><label>{{ t('协议') }}<select :aria-label="t('筛选协议')" v-model="modelProtocol" :disabled="busy||modelLoading" @change="searchModels"><option value="">{{ t('全部协议') }}</option><option value="chat">Chat Completions</option><option value="messages">Messages</option><option value="responses">Responses</option></select></label><label v-if="admin">{{ t('状态') }}<select :aria-label="t('筛选模型状态')" v-model="modelStatus" :disabled="busy||modelLoading" @change="searchModels"><option value="">{{ t('全部状态') }}</option><option value="priced">{{ t('已定价') }}</option><option value="unpriced">{{ t('缺少价格') }}</option><option value="unavailable">{{ t('无可用账号') }}</option><option value="disabled">{{ t('已停用') }}</option></select></label><label>{{ t('每页') }}<select :aria-label="t('每页')" v-model.number="modelPageSize" :disabled="busy||modelLoading" @change="searchModels"><option :value="10">{{ t('10 项') }}</option><option :value="20">{{ t('20 项') }}</option><option :value="50">{{ t('50 项') }}</option><option :value="100">{{ t('100 项') }}</option></select></label><button class="secondary" :disabled="busy||modelLoading">{{ t('搜索') }}</button><button type="button" class="secondary" :disabled="busy||modelLoading" @click="modelSearch='';modelAccount='';modelProtocol='';modelStatus='';searchModels()">{{ t('清除') }}</button></form><div v-if="!models.length" class="empty"><span class="empty-icon">◇</span><h3>{{ (modelSearch||modelAccount||modelProtocol||modelStatus)?t('没有匹配的模型'):admin?t('等待同步模型'):t('暂无可用模型') }}</h3><p>{{ (modelSearch||modelAccount||modelProtocol||modelStatus)?t('请调整筛选或搜索条件。'):admin?t('添加上游账号后，点击「验证并同步」获取模型目录。'):t('请联系管理员配置并启用模型。') }}</p></div><div v-else class="table-wrap"><table class="model-price-table"><thead><tr><th>{{ t('模型 ID') }}</th><th>{{ t('平台') }}</th><th>{{ t('上游模型') }}</th><th>{{ t('协议') }}</th><th>{{ t('状态') }}</th><th>{{ t('输入') }}</th><th>{{ t('输出') }}</th><th>{{ t('缓存读取') }}</th><th></th></tr></thead><tbody><tr v-for="m in models" :key="m.id"><td class="model-id-cell" :title="m.id"><b>{{ m.id }}</b></td><td>{{ providerLabel(m.provider) }}</td><td class="model-id-cell" :title="m.upstream_id">{{ m.upstream_id }}</td><td>{{ (m.protocols?.length?m.protocols:[m.protocol]).map(p=>p==='chat'?'Chat Completions':p==='responses'?'Responses':'Messages').join(' / ') }}</td><td><span :class="['pill',{'muted-pill':!m.enabled||!m.price}]">{{ !m.enabled?t('已停用'):!m.available?t('无可用账号'):m.price?(admin?t('已定价'):t('可用')):t('缺少价格') }}</span></td><td>{{ m.price?usd(m.price.input):'—' }}</td><td>{{ m.price?usd(m.price.output):'—' }}</td><td>{{ m.price?usd(m.price.cached):'—' }}</td><td><button v-if="admin" class="text-button" :disabled="modelLoading" @click="open('price',m)">{{ t('编辑价格') }}</button><button v-else class="text-button" :aria-label="t('复制模型 ID：')+m.id" @click="copy(m.id)">{{ t('复制 ID') }}</button></td></tr></tbody></table></div><div class="model-pagination"><span>{{ t('共 {0} 项 · 第 {1} / {2} 页',[modelTotal,modelPage,modelPages]) }}</span><div class="actions"><button class="secondary" :disabled="busy||modelLoading||modelPage<=1" @click="turnModelPage(-1)">{{ t('上一页') }}</button><button class="secondary" :disabled="busy||modelLoading||modelPage>=modelPages" @click="turnModelPage(1)">{{ t('下一页') }}</button></div></div></section></template>
    <RuntimeLogs v-if="page==='runtime'&&admin" ref="runtimeLogs" :api="api" />
    <template v-if="page==='audit'"><section class="panel"><form class="model-search audit-search" @submit.prevent="searchAudit"><label>{{ t('管理员 ID') }}<input v-model="auditFilter.actor_id" type="number" min="1" step="1" :placeholder="t('全部管理员')"></label><label>{{ t('操作') }}<input v-model="auditFilter.action" maxlength="200" :placeholder="t('操作名称关键词')"></label><label>{{ t('目标 ID') }}<input v-model="auditFilter.target_id" type="number" min="1" step="1" :placeholder="t('全部目标')"></label><label>{{ t('详情') }}<input v-model="auditFilter.details" maxlength="200" :placeholder="t('详情关键词')"></label><label>{{ t('开始时间') }}<input v-model="auditFilter.since" type="datetime-local"></label><label>{{ t('结束时间') }}<input v-model="auditFilter.until" type="datetime-local" :min="auditFilter.since||undefined"></label><button class="secondary" :disabled="busy||auditLoading">{{ t('筛选') }}</button><button type="button" class="secondary" :disabled="busy||auditLoading" @click="clearAudit">{{ t('清除') }}</button></form><div v-if="!audit.length" class="empty"><h3>{{ t('暂无符合条件的操作记录') }}</h3></div><div v-else class="table-wrap"><table><thead><tr><th>{{ t('时间') }}</th><th>{{ t('管理员') }}</th><th>{{ t('操作') }}</th><th>{{ t('目标') }}</th><th>{{ t('详情') }}</th></tr></thead><tbody><tr v-for="a in audit" :key="a.id"><td>{{ date(a.created_at) }}</td><td>{{ a.actor_id?'#'+a.actor_id:'—' }}</td><td><code>{{ a.action }}</code></td><td>{{ a.target_id?'#'+a.target_id:'—' }}</td><td class="detail-cell">{{ typeof a.details==='string'?a.details:JSON.stringify(a.details) }}</td></tr></tbody></table></div><div class="model-pagination"><span>{{ t('共 {0} 项 · 第 {1} / {2} 页',[auditTotal,auditPage,auditPages]) }}</span><div class="actions"><label class="page-size">{{ t('每页') }}<select :aria-label="t('操作记录每页条数')" v-model.number="auditPageSize" :disabled="busy||auditLoading" @change="searchAudit"><option :value="10">10</option><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select></label><button class="secondary" :disabled="busy||auditLoading||auditPage<=1" @click="turnAuditPage(-1)">{{ t('上一页') }}</button><button class="secondary" :disabled="busy||auditLoading||auditPage>=auditPages" @click="turnAuditPage(1)">{{ t('下一页') }}</button></div></div></section></template>
    <template v-if="page==='settings'"><div class="settings-tabs" role="tablist" :aria-label="t('系统设置分类')"><button v-for="(tab,index) in settingsTabs" :key="tab.id" :id="'settings-tab-'+tab.id" role="tab" :aria-selected="settingsTab===tab.id" :aria-controls="'settings-panel-'+tab.id" :tabindex="settingsTab===tab.id?0:-1" @click="settingsTab=tab.id" @keydown="moveSettingsTab($event,index)">{{ tab.name }}</button></div><div id="settings-panel-email" role="tabpanel" aria-labelledby="settings-tab-email" v-show="settingsTab==='email'"><EmailSettings ref="emailSettingsForm" :api="api" :notify="notify" :email="user.email||''"/></div><div id="settings-panel-backup" role="tabpanel" aria-labelledby="settings-tab-backup" v-show="settingsTab==='backup'"><BackupSettings v-if="settingsTab==='backup'" ref="backupSettingsForm" :api="api" :notify="notify"/></div><section id="settings-panel-logs" role="tabpanel" aria-labelledby="settings-tab-logs" v-show="settingsTab==='logs'" class="panel settings-panel"><h2>{{ t('请求日志') }}</h2><p class="subtle">{{ t('自动清理超过保留期限的请求日志，不影响额度统计与结算记录。') }}</p><form @submit.prevent="action(async()=>{await api('/admin/settings',{method:'PUT',body:{log_retention_days:Number(days)}});notify(t('日志保留期限已保存'))})"><label>{{ t('保留天数') }}<input v-model="days" type="number" min="1" max="3650" required></label><button class="primary" :disabled="busy">{{ t('保存设置') }}</button></form></section><section id="settings-panel-security" role="tabpanel" aria-labelledby="settings-tab-security" v-show="settingsTab==='security'" class="panel settings-panel"><h2>{{ t('账号安全') }}</h2><p class="subtle">{{ t('修改密码会撤销你的所有登录会话，需要重新登录。') }}</p><button class="secondary" @click="open('password')">{{ t('修改密码') }}</button></section></template>
    <footer class="page-footer"><span>FiftyAPI</span><span>{{ t('小团队的模型连接与额度管理') }}</span><span>{{ t('USD 为内部额度单位') }}</span></footer>
