 </div>
 <div v-if="modal" class="modal-backdrop" @click.self="close"><section :class="['modal',{'contribution-links-dialog':modal==='contribution-links','account-config-dialog':modal==='config'||modal==='gateway'||modal==='key-usage','account-model-dialog':modal==='account-models'||modal==='routing'||modal==='attempts'}]" role="dialog" aria-modal="true" :aria-label="modalTitle"><header><h2>{{ modalTitle }}</h2><button class="icon-button" :aria-label="t('关闭')" :disabled="busy" @click="close">×</button></header><form @submit.prevent="save"><div class="modal-body">
  <KeyUsage v-if="modal==='key-usage'" :api="api" :token="form.token||''" :key-name="form.name||''" @copy="copy"/>
  <ContributionLinks v-if="modal==='contribution-links'" :api="api"/>
  <AccountImport v-if="modal==='import'" ref="accountImportForm" :api="api" :busy="busy"/>
  <AccountRouting v-if="modal==='routing'" ref="accountRoutingForm" :account="form" :api="api" :busy="busy" @reset="resetRouting" @quota="queryQuota"/>
  <RequestAttempts v-if="modal==='attempts'" :id="form.id" :api="api" :admin="admin"/>
  <template v-if="modal==='rename-account'"><label>{{ t('账号名称') }}<input v-model="form.name" required maxlength="128" :aria-label="t('账号名称')"></label></template>
  <AccountModels v-if="modal==='account-models'" :key="form.id+':'+accountModelsRevision" :account="form" :api="api" :busy="busy" @sync="verify" @copy="copy"/>
  <template v-if="modal==='gateway'"><label>{{ t('网关名称') }}<input v-model="form.name" required maxlength="128" :placeholder="t('例如：团队 New API')"></label><AccountConfigForm v-model="form.config" provider="gateway" :creating="true"/></template><template v-if="modal==='config'"><AccountConfigForm v-model="form.config" :provider="form.provider"/></template><template v-if="modal==='key'"><template v-if="!secret"><label>{{ t('密钥名称') }}<input v-model="form.name" required maxlength="80" :placeholder="t('例如：工作电脑 · Claude Code')"></label><p class="subtle">{{ t('为不同工具单独创建密钥，方便管理和撤销。') }}</p></template><template v-else><div class="notice">{{ t('密钥已创建，请妥善保管。之后也可在密钥列表中复制。') }}</div><div class="secret-box"><code>{{ secret }}</code></div><button type="button" class="secondary" @click="copy(secret)">{{ t('复制密钥') }}</button><button type="button" class="text-button" @click="open('key-usage',{token:secret,name:form.name})">{{ t('使用密钥') }}</button></template></template>
  <template v-if="modal==='user'"><div v-if="!mailConfigured" class="notice">{{ t('尚未配置邮件服务，请在「系统设置 → 邮件配置」中配置并启用。') }}</div><label>{{ t('邮箱') }}<input v-model="form.email" type="email" required maxlength="254" autocomplete="off" placeholder="member@example.com"></label><label>{{ t('显示名称（选填）') }}<input v-model="form.display_name" maxlength="80" autocomplete="off"></label><p class="subtle">{{ t('系统发送一次性设置密码链接，24 小时内有效，不通过邮件发送密码。') }}</p></template>
  <template v-if="modal==='user'||modal==='quota'"><div class="two-columns"><label>{{ t('5 小时额度（USD）') }}<input v-model="form.limit5" type="number" min="0" step="0.000001" required></label><label>{{ t('每周额度（USD）') }}<input v-model="form.limit7" type="number" min="0" step="0.000001" required></label></div><p class="subtle">{{ t('三家平台共享额度。修改上限不会清空已使用金额；0 表示没有可用额度。') }}</p></template>
  <template v-if="modal==='price'"><p class="subtle break">{{ form.id }}</p><p class="subtle">{{ t('支持协议：') }}{{ (form.protocols?.length?form.protocols:[form.protocol]).map(p=>p==='chat'?'Chat Completions':p==='responses'?'Responses':'Messages').join(' / ') }}{{ t('。协议在上游账号配置中修改，价格供该模型支持的协议共用。') }}</p><div class="two-columns"><label v-for="[k,l] in [['input',t('输入')],['output',t('输出')],['cached',t('缓存读取')],['cache_write',t('缓存写入')]]" :key="k">{{ l }}{{ t('（USD / 百万 Token）') }}<input v-model="form[k]" type="number" min="0" step="0.000001" required></label></div><label class="checkbox"><input v-model="form.enabled" type="checkbox">{{ t('启用模型') }}</label><p class="subtle">{{ t('新价格只影响后续请求，历史请求保留原价格快照。') }}</p></template>
  <template v-if="modal==='oauth'"><template v-if="!oauth"><label>{{ t('账号名称') }}<input v-model="form.name" required maxlength="128" :disabled="Boolean(form.account_id)" :placeholder="t('例如：团队 Antigravity')"></label><label>{{ t('上游平台') }}<select v-model="form.provider" :disabled="Boolean(form.account_id)"><option value="antigravity">Antigravity</option><option value="claude">Claude Code</option><option value="openai">OpenAI Codex</option></select></label><p class="subtle">{{ t('将生成授权链接，在浏览器完成后复制授权结果回到这里。') }}</p></template><template v-else><div class="notice">{{ t('请保持此窗口，授权会话 10 分钟内有效。') }}</div><a :href="oauth.auth_url" target="_blank" rel="noopener noreferrer" class="primary link-button">{{ t('打开授权页面 ↗') }}</a><button type="button" class="text-button" style="margin-left:12px" @click="oauth=null;form.result='';error=''">{{ t('重新生成链接') }}</button><label>{{ t('授权结果') }}<textarea v-model="form.result" required rows="4" autocomplete="off" :placeholder="t('粘贴完整回调 URL 或 code#state')"></textarea></label><p class="subtle">{{ t('如果 localhost 回调页面无法连接，复制地址栏中的完整 URL 即可。授权结果只用于这次换码。') }}</p><label v-if="form.provider==='antigravity'" class="checkbox"><input v-model="form.onboard" type="checkbox">{{ t('缺少项目时，按上游默认 tier 初始化服务') }}</label></template></template>
  <template v-if="modal==='password'||modal==='reset-password'"><label v-if="modal==='password'">{{ t('原密码') }}<input v-model="form.old_password" type="password" required autocomplete="current-password"></label><label>{{ t('新密码') }}<input v-model="form.password" type="password" required minlength="8" maxlength="72" autocomplete="new-password"></label><p class="subtle">{{ t('保存后该账号的已有登录会话全部失效。') }}</p></template>
  <template v-if="modal==='settlement'"><dl class="settlement-details"><dt>{{ t('请求 ID') }}</dt><dd class="break">{{ form.id }}</dd><dt>{{ t('模型') }}</dt><dd class="break">{{ form.model_id }}</dd><dt>{{ t('用户') }}</dt><dd>#{{ form.user_id }}</dd><dt>{{ t('状态') }}</dt><dd>{{ form.status==='pending'?t('结算异常'):form.status==='settled'?t('已结算'):t('处理中') }}</dd><dt>{{ t('原预占') }}</dt><dd>{{ usd(form.reservation) }}</dd><dt>{{ t('已结算金额') }}</dt><dd>{{ form.status==='settled'?usd(form.amount):t('尚未结算') }}</dd><dt>{{ t('原因') }}</dt><dd class="break">{{ t(form.error||'正常完成') }}</dd><dt>{{ t('请求价格快照') }}</dt><dd>{{ form.price_valid?t('输入 {0} / 输出 {1} / 缓存读取 {2} / 缓存写入 {3}（每百万 Token）',[usd(form.price.input),usd(form.price.output),usd(form.price.cached),usd(form.price.cache_write)]):t('价格快照损坏或不可读') }}</dd></dl><div v-if="form.status==='pending'" class="actions"><button type="button" class="secondary" :disabled="busy" @click="retrySettlement(form)">{{ t('重试结算') }}</button><button type="button" class="danger-text" :disabled="busy" @click="open('settle',form)">{{ t('人工核算') }}</button></div></template>
  <template v-if="modal==='settle'"><p class="subtle">{{ t('请求') }} {{ form.id }}</p><label>{{ t('确认消耗（USD）') }}<input v-model="form.amount" type="number" min="0" max="1000000000" step="0.000001" required></label><label>{{ t('核算依据') }}<textarea v-model="form.reason" rows="3" required minlength="3" maxlength="200" :placeholder="t('填写确认用量或释放预占的依据')"></textarea></label><div class="notice">{{ t('预占') }} {{ usd(form.reservation) }} · {{ t(form.error||'上游未返回可靠用量') }}</div><p class="subtle">{{ t('结算将记入请求原来的窗口。输入 0 会释放原预占，此操作记录在审计日志中。') }}</p></template>
  <div v-if="error" class="alert error" role="alert">{{ t(error) }}</div></div><footer><button type="button" class="secondary" @click="close" :disabled="busy">{{ secret?t('完成'):(modal==='key-usage'||modal==='contribution-links'||modal==='settlement'||modal==='account-models'||modal==='attempts'||(modal==='import'&&accountImportForm?.done))?t('关闭'):t('取消') }}</button><button v-if="!secret&&modal!=='key-usage'&&modal!=='contribution-links'&&modal!=='settlement'&&modal!=='account-models'&&modal!=='attempts'&&!(modal==='import'&&accountImportForm?.done)" class="primary" :disabled="busy||(modal==='user'&&!mailConfigured)||(modal==='routing'&&!accountRoutingForm?.ready)">{{ busy?t('正在处理…'):modal==='oauth'&&!oauth?t('生成授权链接'):modal==='user'?t('发送邀请'):modal==='import'?t('批量导入'):t('保存') }}</button></footer></form></section></div>
 <div v-if="toast" class="toast" role="status">✓ {{ t(toast) }}</div>
</template>
